package com.kaipai.service.ai.profileimport; import com.fasterxml.jackson.databind.ObjectMapper; import com.kaipai.model.ai.dto.ProfileImportApplyReqDTO; import java.nio.charset.StandardCharsets; import java.security.MessageDigest; import java.util.HexFormat; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component;
@Component @RequiredArgsConstructor public class ProfileImportPayloadHasher { private final ObjectMapper mapper; public String hash(ProfileImportApplyReqDTO request){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsString(request).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}} }
